/**
 * Whether a right click is used by the block, as the vanilla client predicts it (Block.use up to 1.20.4,
 * Block.useItemOn and, for the main hand, useWithoutItem from 1.20.5), and whether the client swings then.
 *
 * blockInteractionsData.json is generated by scripts/blocks from the decompiled clients of 1.7.10 to 26.3: for each
 * block the versions from which its entry changes. An entry is { kind: always | conditional | itemOnly, cond?, items?,
 * swing?, swingCond?, offhand? }, the conditions a small expression language over the block state, the item in the
 * hand and the player.
 */
import { Block } from 'prismarine-block'
import type { HandContext, InteractionResult } from './interactionRules'
import { itemToBlockRemaps } from './itemBlocksStatic'
import data from './blockInteractionsData.json'
import { versionToNumber } from './utils'

interface BlockEntry {
  kind: 'always' | 'conditional' | 'itemOnly'
  cond?: string
  items?: string[]
  swing?: boolean
  swingCond?: string
  offhand?: boolean | string
}

const blocksTable = data.blocks as unknown as Record<string, Array<[string, BlockEntry | null]>>
const groupsTable = data.groups as unknown as Record<string, Array<[string, string[]]>>

interface EvalContext {
  props: Record<string, any>
  held: string | null
  offhand: string | null
  gamemode: string
  food: number
  face: string
  hit?: { x: number, y: number, z: number }
  dimension?: string
  groups: (name: string) => string[]
  isBlockItem: (name: string) => boolean
}

type Predicate = (c: EvalContext) => boolean

const FACES = ['down', 'up', 'north', 'south', 'west', 'east']
const axis = (d: string) => (d === 'up' || d === 'down' ? 'y' : d === 'north' || d === 'south' ? 'z' : 'x')

const globCache = new Map<string, RegExp>()
const glob = (g: string, s: string) => {
  if (!g.includes('*')) return g === s
  let re = globCache.get(g)
  if (!re) {
    re = new RegExp('^' + g.split('*').map(x => x.replace(/[.+?^${}()|[\]\\]/g, '\\$&')).join('.*') + '$')
    globCache.set(g, re)
  }
  return re.test(s)
}

function matchItem(c: EvalContext, item: string | null, list: string[]) {
  if (!item) return false
  return list.some(e => {
    if (e === '@block_item') return c.isBlockItem(item)
    if (e.startsWith('@')) return c.groups(e.slice(1)).some(g => glob(g, item))
    return glob(e, item)
  })
}

const ATOMS: Record<string, Predicate> = {
  emptyHand: c => !c.held,
  mayBuild: c => c.gamemode !== 'adventure' && c.gamemode !== 'spectator',
  creative: c => c.gamemode === 'creative',
  // creative and operator: the operator level is not known, creative stands in
  opCreative: c => c.gamemode === 'creative',
  hungry: c => c.gamemode === 'creative' || c.gamemode === 'spectator' || c.food < 20,
  hitFacing: c => c.face === c.props.facing,
  hitFacingAxis: c => axis(c.face) === axis(c.props.facing),
  candleHit: c => (c.hit ? c.hit.y > 0.5 : true),
  // the flower pot's plant (before 1.13) is in its block entity: assumed empty
  potEmpty: () => true,
  // the chiseled bookshelf slot under the cursor: any occupied slot stands in
  hitSlotOccupied: c => Object.entries(c.props).some(([k, v]) => /^slot_\d_occupied$/.test(k) && (v === true || v === 'true')),
  // the sign's wax is in its block entity
  signWaxed: () => false,
  anchorWorks: c => c.dimension === 'the_nether' || c.dimension === 'minecraft:the_nether' || c.dimension === 'nether',
  wireDotOrCross: c => {
    const sides = ['north', 'south', 'east', 'west'].map(d => c.props[d])
    return sides.every(x => x === 'none') || sides.every(x => x === 'side')
  },
  bellProperHit: c => {
    if (axis(c.face) === 'y' || (c.hit && c.hit.y > 0.8124)) return false
    const attachment = c.props.attachment
    if (attachment === 'floor') return axis(c.props.facing) === axis(c.face)
    if (attachment === 'single_wall' || attachment === 'double_wall') return axis(c.props.facing) !== axis(c.face)
    return attachment === 'ceiling'
  }
}

function parse(src: string): Predicate {
  let i = 0
  const ws = () => { while (src[i] === ' ') i++ }
  const expr = (): Predicate => {
    let left = term()
    ws()
    while (src[i] === '|') {
      i++
      const right = term()
      const a = left
      left = c => a(c) || right(c)
      ws()
    }
    return left
  }
  const term = (): Predicate => {
    let left = factor()
    ws()
    while (src[i] === '&') {
      i++
      const right = factor()
      const a = left
      left = c => a(c) && right(c)
      ws()
    }
    return left
  }
  const factor = (): Predicate => {
    ws()
    if (src[i] === '!') {
      i++
      const f = factor()
      return c => !f(c)
    }
    if (src[i] === '(') {
      i++
      const e = expr()
      ws()
      if (src[i++] !== ')') throw new Error(`expected ) in ${src}`)
      return e
    }
    return atom()
  }
  const atom = (): Predicate => {
    const m = /^([a-zA-Z_]+)(\(([^)]*)\)|\s*(>=|<=|!=|=|<|>)\s*([a-z0-9_]+))?/.exec(src.slice(i))
    if (!m) throw new Error(`bad atom at ${i} in ${src}`)
    i += m[0].length
    const name = m[1]!
    const args = m[3]
    const op = m[4]
    const val = m[5]!
    if (args !== undefined) {
      const list = args.split(',').map(s => s.trim())
      if (name === 'holding') return c => matchItem(c, c.held, list)
      if (name === 'offhandHolding') return c => matchItem(c, c.offhand, list)
      throw new Error(`unknown function ${name} in ${src}`)
    }
    if (op) {
      if (name === 'face') return c => (op === '=' ? c.face === val : c.face !== val)
      const num = Number(val)
      return c => {
        const p = c.props[name]
        if (p === undefined) return false
        const pv = Number.isNaN(num) ? String(p) : Number(p)
        const v = Number.isNaN(num) ? val : num
        switch (op) {
          case '=': return pv === v
          case '!=': return pv !== v
          case '<': return pv < v
          case '<=': return pv <= v
          case '>': return pv > v
          case '>=': return pv >= v
        }
        return false
      }
    }
    if (ATOMS[name]) return ATOMS[name]
    // a boolean block state property
    return c => c.props[name] === true || c.props[name] === 'true'
  }
  const f = expr()
  ws()
  if (i !== src.length) throw new Error(`trailing input in ${src} at ${i}`)
  return f
}

const compiled = new Map<string, Predicate>()
const condition = (src: string) => {
  let f = compiled.get(src)
  if (!f) {
    f = parse(src)
    compiled.set(src, f)
  }
  return f
}

/** the data's version for a version: the sources cover these versions with their neighbours */
function dataVersion(version: string) {
  if (/^1\.13(\.[01])?$/.test(version)) return versionToNumber('1.13.2')
  if (/^1\.14(\.[0-3])?$/.test(version)) return versionToNumber('1.14.4')
  if (/^1\.17(\.\d)?$/.test(version)) return versionToNumber('1.18.1') // no 1.17 source; 1.18 added no interactive blocks
  return versionToNumber(version)
}

function entryAt<T>(list: Array<[string, T]> | undefined, version: number): T | undefined {
  if (!list) return undefined
  let found: T | undefined
  for (const [v, value] of list) {
    if (versionToNumber(v) <= version) found = value
  }
  return found
}

export function getBlockEntry(version: string, blockName: string): BlockEntry | null {
  return entryAt(blocksTable[blockName], dataVersion(version)) ?? null
}

function evalContext(ctx: HandContext, block: Block, held: string | null): EvalContext {
  const version = dataVersion(ctx.data.version.minecraftVersion!)
  let props: Record<string, any> = {}
  try {
    props = block.getProperties?.() ?? {}
  } catch {}
  // before 1.13 there are no named properties
  if (ctx.version['<']('1.13')) {
    if (/cauldron/.test(block.name)) props = { ...props, level: block.metadata }
    if (block.name === 'jukebox') props = { ...props, has_record: block.metadata === 1 }
  }
  const face = FACES[(block as any).face] ?? 'up'
  const intersect = (block as any).intersect
  return {
    props,
    held,
    offhand: ctx.offItem?.name ?? null,
    gamemode: ctx.gameMode,
    food: ctx.bot.food ?? 20,
    face,
    hit: intersect ? { x: intersect.x - block.position.x, y: intersect.y - block.position.y, z: intersect.z - block.position.z } : undefined,
    dimension: (ctx.bot.game as any)?.dimension,
    groups: (name) => entryAt(groupsTable[name], version) ?? [],
    isBlockItem: (name) => !!ctx.data.blocksByName[(itemToBlockRemaps as Record<string, string>)[name] ?? name]
  }
}

function consumes(entry: BlockEntry, c: EvalContext) {
  if (entry.kind === 'always') return true
  const cond = entry.cond ? condition(entry.cond)(c) : true
  if (entry.kind === 'itemOnly') return matchItem(c, c.held, entry.items ?? []) && cond
  return cond
}

/** the block's use of a right click by the hand: success (the client swings), consume (no swing) or pass */
export function blockUseResult(ctx: HandContext, block: Block): InteractionResult {
  const entry = getBlockEntry(ctx.data.version.minecraftVersion!, block.name)
  if (!entry) return 'pass'
  const c = evalContext(ctx, block, ctx.item?.name ?? null)
  let used: boolean
  if (ctx.hand === 1 && entry.offhand !== undefined) {
    // 1.20.5+: only useItemOn runs for the off hand
    used = typeof entry.offhand === 'boolean' ? entry.offhand : condition(entry.offhand)(c)
  } else {
    used = consumes(entry, c)
  }
  if (!used) return 'pass'
  if (entry.swing === false) return 'consume'
  if (entry.swingCond && !condition(entry.swingCond)(c)) return 'consume'
  return 'success'
}

/** every condition of the data parses (for the tests) */
export function parseAllConditions() {
  let count = 0
  for (const list of Object.values(blocksTable)) {
    for (const [, entry] of list) {
      if (!entry) continue
      for (const src of [entry.cond, entry.swingCond, typeof entry.offhand === 'string' ? entry.offhand : undefined]) {
        if (src) {
          parse(src)
          count++
        }
      }
    }
  }
  return count
}
